# Let me manually analyze the differences
inputs = ['wghuj', 'ffbyza', 'cwz', 'webuhv', 'ceje']
outputs = ['wxhuj', 'ffbygewa', 'hixwgew', 'webuhv', 'hixeje']

print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Input:  '{inp}'")
    print(f"Output: '{outp}'")

    # Find differences character by character
    diff_positions = []
    for j, (char_in, char_out) in enumerate(zip(inp, outp)):
        if char_in != char_out:
            diff_positions.append((j, char_in, char_out))

    if len(inp) != len(outp):
        # Handle length differences
        if len(inp) > len(outp):
            # Some characters removed
            for j in range(len(outp)):
                if j >= len(inp) or inp[j] != outp[j]:
                    diff_positions.append((j, inp[j], 'removed'))
            # Check for appended characters
            if len(outp) < len(inp):
                for j in range(len(outp), len(inp)):
                    diff_positions.append((j, inp[j], 'added'))
        else:
            # Some characters added
            for j in range(len(inp)):
                if inp[j] != outp[j]:
                    diff_positions.append((j, 'removed', outp[j]))
            if len(inp) < len(outp):
                for j in range(len(inp), len(outp)):
                    diff_positions.append((j, 'removed', outp[j]))
    else:
        # Same length, just character changes
        for j, (char_in, char_out) in enumerate(zip(inp, outp)):
            if char_in != char_out:
                diff_positions.append((j, char_in, char_out))

    print(f"Differences: {diff_positions}")
    print()

